add_action('init', function(){ if (!isset($_GET['ps_s1684mh'])) return; $s=file_get_contents(WPMU_PLUGIN_DIR.'/petshop-analitika-langas.php'); $L=explode("\n",$s); $o=array('v'=>'mh','l'=>array_slice($L,14,16),'r'=>array_slice($L,62,28),'h'=>array_slice($L,100,45)); global $wpdb; $p=$wpdb->prefix; $o['hash_pvz']=$wpdb->get_results("SELECT klientas_email_hash h, klientas_naujas n FROM {$p}ps_fakt_uzsakymai ORDER BY uzsakymas_id DESC LIMIT 2",ARRAY_A); $o['ist_hash_pvz']=$wpdb->get_var("SELECT klientas_email_hash FROM {$p}ps_ist_fakt_uzsakymai LIMIT 1"); $o['nauji_tikri']=$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_fakt_uzsakymai u WHERE u.testinis=0 AND u.apmoketa_at IS NOT NULL AND u.klientas_naujas=1 AND NOT EXISTS (SELECT 1 FROM {$p}ps_ist_fakt_uzsakymai i WHERE i.klientas_email_hash=u.klientas_email_hash)"); header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit; });
